const hasText = (value) => typeof value === "string" && value.trim().length > 0;

Object.keys(resources).forEach((code) => {
  resources[code].translation = {
    ...base,
    ...Object.fromEntries(Object.entries(resources[code].translation).filter(([, value]) => hasText(value))),
    ...Object.fromEntries(Object.entries(adminTranslations[code] || {}).filter(([, value]) => hasText(value))),
  };
});

